ALTER TABLE "shop_listings" ADD CONSTRAINT "shop_listings_prices_valid" CHECK ("shop_listings"."online_price" >= 0 AND "shop_listings"."online_price" <> 'NaN'::numeric AND "shop_listings"."counter_price" >= 0 AND "shop_listings"."counter_price" <> 'NaN'::numeric AND "shop_listings"."mrp" >= 0 AND "shop_listings"."mrp" <> 'NaN'::numeric AND "shop_listings"."online_price" <= "shop_listings"."mrp" AND "shop_listings"."counter_price" <= "shop_listings"."mrp" AND "shop_listings"."low_stock_level" >= 0 AND "shop_listings"."low_stock_level" <> 'NaN'::numeric);